<?php
declare(strict_types=1);
require dirname(__DIR__) . '/app/bootstrap.php';

$categories=$products=$banners=[];$selectedCategory=null;$selectedCategorySlug=trim((string)($_GET['category']??''));$dbReady=true;$storeName='معسلات VIP 27';$heroTitle='معسلات VIP 27';$heroSubtitle='اكتشف تجربة تسوق راقية، بتفاصيل مختارة بعناية وخدمة تليق بك.';
try {
 $pdo=db();
 $categories=$pdo->query("SELECT id,name,slug,image_path FROM categories WHERE is_active=1 AND compliance_status='approved' ORDER BY sort_order,name LIMIT 40")->fetchAll();
 if($selectedCategorySlug!==''){$categoryQuery=$pdo->prepare("SELECT id,name,slug FROM categories WHERE slug=? AND is_active=1 AND compliance_status='approved' LIMIT 1");$categoryQuery->execute([$selectedCategorySlug]);$selectedCategory=$categoryQuery->fetch()?:null;if(!$selectedCategory)$selectedCategorySlug='';}
 $productSql="SELECT p.id,p.name,p.slug,p.price,(p.stock_quantity-p.reserved_quantity) available_quantity,p.short_description,(SELECT pi.image_path FROM product_images pi WHERE pi.product_id=p.id ORDER BY pi.is_primary DESC,pi.sort_order ASC LIMIT 1) image_path FROM products p JOIN categories c ON c.id=p.category_id WHERE p.status='active' AND p.compliance_status='approved' AND c.is_active=1 AND c.compliance_status='approved'";
 if($selectedCategory){$productSql.=" AND p.category_id=?";}$productSql.=" ORDER BY p.is_featured DESC,p.created_at DESC LIMIT 24";$productQuery=$pdo->prepare($productSql);$productQuery->execute($selectedCategory?[(int)$selectedCategory['id']]:[]);$products=$productQuery->fetchAll();
 $settings=$pdo->query("SELECT setting_key,setting_value FROM settings WHERE setting_key IN ('store_name','hero_title','hero_subtitle')")->fetchAll();
 foreach($settings as $s){if($s['setting_key']==='store_name'&&$s['setting_value'])$storeName=$s['setting_value'];if($s['setting_key']==='hero_title'&&$s['setting_value'])$heroTitle=$s['setting_value'];if($s['setting_key']==='hero_subtitle'&&$s['setting_value'])$heroSubtitle=$s['setting_value'];}
 $banners=$pdo->query("SELECT title,subtitle,image_path,button_label,button_url FROM banners WHERE is_active=1 AND image_path IS NOT NULL AND image_path<>'' ORDER BY sort_order,id")->fetchAll();
} catch(Throwable $e){$dbReady=false;error_log('Storefront database error: '.$e->getMessage());}
$cartCount=array_sum(array_map('intval',$_SESSION['cart']??[]));$csrf=\App\Security::csrfToken();
