<main>
<section class="hero <?= $banners?'hero-slideshow':'' ?>" id="hero">
<?php if($banners):?><div class="hero-slides"><?php foreach($banners as $i=>$banner):?><article class="hero-slide <?=$i===0?'is-active':''?>" aria-hidden="<?=$i===0?'false':'true'?>"><img class="hero-slide-image" src="<?=e($banner['image_path'])?>" alt="<?=e($banner['image_alt']??$banner['title'])?>" fetchpriority="<?=$i===0?'high':'low'?>"><div class="hero-slide-shade"></div><div class="container hero-content"><div class="hero-copy"><span class="eyebrow">مرحباً بكم في</span><h1><?=e($banner['title']?:$heroTitle)?></h1><?php if($banner['subtitle']):?><p><?=e($banner['subtitle'])?></p><?php endif;?><?php if($banner['button_label']&&$banner['button_url']):?><div class="hero-actions"><a class="btn btn-gold" href="<?=e($banner['button_url'])?>"><?=e($banner['button_label'])?></a></div><?php else:?><div class="hero-actions"><a class="btn btn-gold" href="#products">تسوق الآن ←</a></div><?php endif;?></div></div></article><?php endforeach;?></div><?php if(count($banners)>1):?><div class="hero-dots" aria-label="التنقل بين العروض"><?php foreach($banners as $i=>$banner):?><button type="button" class="<?=$i===0?'active':''?>" data-slide-to="<?=$i?>" aria-label="العرض <?=$i+1?>"></button><?php endforeach;?></div><button class="hero-arrow hero-prev" type="button" aria-label="السابق">‹</button><button class="hero-arrow hero-next" type="button" aria-label="التالي">›</button><?php endif;?>
<?php else:?><div class="hero-glow"></div><div class="container hero-content"><div class="hero-copy"><span class="eyebrow">مرحباً بكم في</span><h1><?=e($heroTitle)?></h1><p><?=e($heroSubtitle)?></p><div class="hero-actions"><a class="btn btn-gold" href="#products">تسوق الآن ←</a><a class="text-link" href="#categories">تصفح الأقسام</a></div><div class="trust-row"><span>✧ جودة مختارة</span><span>◇ تجربة سهلة</span><span>◈ خدمة موثوقة</span></div></div><div class="hero-art" aria-hidden="true"><div class="gold-orbit"></div><div class="hero-emblem">27</div><span class="hero-caption">VIP 27</span></div></div><?php endif;?></section>
