<?php if($categories):?><div class="category-grid" data-category-carousel data-selected-index="<?= $selectedCategory ? (1+array_search($selectedCategorySlug,array_column($categories,'slug'),true)) : 0 ?>"><a class="category-card category-all <?= !$selectedCategory ? 'is-selected' : '' ?>" href="./#products" data-category-card><span class="category-all-icon">✦</span><span class="category-card-caption"><strong>عرض الكل</strong><small>جميع المنتجات</small></span></a><?php foreach($categories as $category):?><a class="category-card <?= $selectedCategory && $selectedCategorySlug===$category['slug'] ? 'is-selected' : '' ?>" data-category-card href="?category=<?=rawurlencode($category['slug'])?>#products"><?php if(!empty($category['image_path'])):?><img class="category-card-image" loading="lazy" src="<?=e($category['image_path'])?>" alt="<?=e($category['name'])?>"><?php else:?><span class="category-icon">✧</span><?php endif;?><span class="category-card-caption"><strong><?=e($category['name'])?></strong><small>عرض المنتجات</small></span></a><?php endforeach;?></div><?php else:?><div class="empty-state"><span>✧</span><h3>نجهز لك تجربة مميزة</h3><p>ستظهر الأقسام المعتمدة هنا فور إضافتها من لوحة الإدارة.</p></div><?php endif;?></div></section>
<section class="section products-section" id="products"><div class="container"><div class="section-heading"><div><span class="eyebrow"><?= $selectedCategory ? 'تتصفح الآن' : 'اختياراتنا لك' ?></span><h2><?= $selectedCategory ? 'منتجات قسم: '.e($selectedCategory['name']) : 'جميع المنتجات' ?></h2></div><a class="section-more" href="categories.php">تصفح الأقسام ←</a></div><nav class="category-filter-bar" aria-label="تصفية المنتجات"><a class="<?= !$selectedCategory ? 'active' : '' ?>" href="./#products">كل المنتجات</a><?php foreach($categories as $category):?><a class="<?= $selectedCategory && $selectedCategorySlug===$category['slug'] ? 'active' : '' ?>" href="?category=<?=rawurlencode($category['slug'])?>#products"><?=e($category['name'])?></a><?php endforeach;?></nav>
<?php if($products):?><div class="product-grid"><?php foreach($products as $product):?><article class="product-card"><a class="product-image" href="product.php?slug=<?=rawurlencode($product['slug'])?>"><?php if($product['image_path']):?><img loading="lazy" src="<?=e($product['image_path'])?>" alt="<?=e($product['name'])?>"><?php else:?><span class="image-placeholder"><?=e($storeName)?></span><?php endif;?></a><div class="product-info"><h3><?=e($product['name'])?></h3><p><?=e($product['short_description'])?></p><div class="product-bottom"><strong><?=number_format((float)$product['price'],2)?> <small>ر.س</small></strong><span class="<?=((int)$product['available_quantity']>0?'available':'unavailable')?>"><?=((int)$product['available_quantity']>0?'متوفر':'غير متوفر')?></span></div><div class="product-actions"><a class="btn btn-outline" href="product.php?slug=<?=rawurlencode($product['slug'])?>">التفاصيل</a><?php if((int)$product['available_quantity']>0):?><form method="post" action="add-to-cart.php"><input type="hidden" name="_csrf" value="<?=e($csrf)?>"><input type="hidden" name="product_id" value="<?=(int)$product['id']?>"><input type="hidden" name="return_to" value="./"><button class="btn btn-gold">أضف للسلة</button></form><?php endif;?></div></div></article><?php endforeach;?></div><?php else:?><div class="empty-state"><span>✧</span><h3><?= $selectedCategory ? 'لا توجد منتجات معتمدة في هذا القسم حالياً' : 'لا توجد منتجات معتمدة حالياً' ?></h3><p><?= $selectedCategory ? 'أضف منتجات معتمدة لهذا القسم أو اختر قسماً آخر.' : 'ستظهر المنتجات هنا بعد إضافتها واعتمادها من لوحة التحكم.' ?></p><a class="btn btn-outline" href="categories.php">استعراض الأقسام</a></div><?php endif;?></div></section>
